param([string]$SourcePath,[string]$EvidenceRoot)
$ErrorActionPreference='Stop'
New-Item -ItemType Directory -Force $EvidenceRoot|Out-Null
$t=$null;$e=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($SourcePath,[ref]$t,[ref]$e)
$names=@('Get-AIPyTeamResponsesHttpError','New-AIPyTeamResponsesRequest','Read-AIPyTeamResponsesResponse','Invoke-AIPyTeamAzureResponses','Invoke-LLMChatCompletion','Resolve-AIPyTeamAzureProtocol')
foreach($f in $ast.FindAll({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst]},$true)|Where-Object {$_.Name -in $names}){. ([scriptblock]::Create($f.Extent.Text))}
$rows=@()
function Check($id,[scriptblock]$test){try{& $test;$script:rows+=@{id=$id;pass=$true}}catch{$script:rows+=@{id=$id;pass=$false;error=$_.Exception.Message}}}
function Assert($ok,$message){if(-not $ok){throw $message}}
function Update-ErrorHandling {param($ErrorRecord,$ErrorContext,$LogFilePath)}
$GlobalState=[pscustomobject]@{VerbosePrompt=$false}
Check 'selector' {Assert ($ast.ParamBlock.Parameters.Name.VariablePath.UserPath -contains 'AzureOpenAIProtocol') 'Public selector missing'; $s=[pscustomobject]@{LLMProvider='AzureOpenAI'};Assert ((Resolve-AIPyTeamAzureProtocol -State $s -Protocol ChatCompletions) -eq 'ChatCompletions') 'legacy default'; $s.AzureOpenAIProtocol='Responses';Assert ((Resolve-AIPyTeamAzureProtocol -State $s -Protocol ChatCompletions) -eq 'Responses') 'saved override'}
Check 'request' {foreach($base in 'https://fixture.invalid','https://fixture.invalid/','https://fixture.invalid/openai/v1/'){ $r=New-AIPyTeamResponsesRequest -Endpoint $base -ApiKey synthetic-key -Deployment opaque-alias -SystemPrompt system -UserPrompt user -MaxTokens 256 -TimeOut 60; $b=$r.Body|ConvertFrom-Json; Assert ($r.Uri -eq 'https://fixture.invalid/openai/v1/responses' -and $r.Headers['api-key'] -eq 'synthetic-key' -and $r.TimeoutSec -eq 60) 'transport';Assert ($b.model -eq 'opaque-alias' -and $b.max_output_tokens -eq 256 -and $b.store -eq $false -and $b.stream -eq $false -and $b.instructions -eq 'system' -and $b.input -eq 'user') 'payload';Assert ($b.PSObject.Properties.Name -notcontains 'temperature' -and $b.PSObject.Properties.Name -notcontains 'top_p' -and $b.PSObject.Properties.Name -notcontains 'max_tokens') 'unsupported params'}}
Check 'shared-dpapi-key' { $secure=ConvertTo-SecureString 'synthetic-shared-key' -AsPlainText -Force; try{$encoded=ConvertFrom-SecureString $secure; $r=New-AIPyTeamResponsesRequest -Endpoint https://fixture.invalid -ApiKey $encoded -Deployment model -MaxTokens 256;Assert ($r.Headers['api-key'] -ceq 'synthetic-shared-key') 'DPAPI key sent without decoding'}finally{$secure.Dispose()} }
Check 'invalid-config' {foreach($base in 'http://fixture.invalid','https://fixture.invalid/openai/deployments/model','https://fixture.invalid/?api-version=v1','https://user:pass@fixture.invalid/'){ $caught=$false;try{New-AIPyTeamResponsesRequest -Endpoint $base -ApiKey key -Deployment model|Out-Null}catch{$caught=$true};Assert $caught 'bad endpoint admitted'}; $caught=$false;try{New-AIPyTeamResponsesRequest -Endpoint https://fixture.invalid -ApiKey '' -Deployment model|Out-Null}catch{$caught=$true};Assert $caught 'missing key admitted';$s=[pscustomobject]@{AzureOpenAIProtocol='bogus'};$caught=$false;try{Resolve-AIPyTeamAzureProtocol -State $s|Out-Null}catch{$caught=$true};Assert $caught 'invalid saved selection'}
Check 'stream-rejected' {$caught=$false;try{New-AIPyTeamResponsesRequest -Endpoint https://fixture.invalid -ApiKey key -Deployment model -Stream $true|Out-Null}catch{$caught=$_.Exception.Message -match 'streaming.*unsupported'};Assert $caught 'stream accepted'}
foreach($case in 'completed','incomplete','error','failed','refusal','toolonly','empty','mixedtool','reasoningtext'){
 Check $case { $r=[pscustomobject]@{status='completed';error=$null;output=@([pscustomobject]@{type='message';role='assistant';content=@([pscustomobject]@{type='output_text';text='AZURE_'},[pscustomobject]@{type='output_text';text='OK'})})};switch($case){failed{$r.status='failed'} mixedtool{$r.output+=@{type='function_call';name='tool'}} reasoningtext{$r.output=@(@{type='reasoning'})+$r.output} incomplete{$r.status='incomplete';$r|Add-Member incomplete_details @{reason='max_output_tokens'}} error{$r.error=@{code='invalid_request_error';param='model'}} refusal{$r.output[0].content=@(@{type='refusal';refusal='no'})} toolonly{$r.output=@(@{type='function_call';name='tool'})} empty{$r.output=@()}};$caught=$false;$text=$null;try{$text=Read-AIPyTeamResponsesResponse $r}catch{$caught=$true}; if($case -in @('completed','reasoningtext')){Assert ($text -eq 'AZURE_OK' -and -not $caught) 'completed text'}else{Assert $caught 'unsafe envelope admitted'} }
}
$env:PSAOAI_API_AZURE_OPENAI_ENDPOINT='https://fixture.invalid/'
$env:PSAOAI_API_AZURE_OPENAI_KEY='synthetic-key'
$script:posts=0
function Invoke-RestMethod {param($Uri,$Method,$Headers,$Body,$TimeoutSec,$ContentType,$ErrorAction) $script:posts++;Assert ($Uri -eq 'https://fixture.invalid/openai/v1/responses' -and $Method -eq 'POST' -and $TimeoutSec -eq 60) 'dispatcher transport'; if($script:fail){throw 'synthetic HTTP400'};[pscustomobject]@{status='completed';output=@(@{type='message';role='assistant';content=@(@{type='output_text';text='AZURE_OK'})})}}
Check 'dispatcher' { $r=Invoke-LLMChatCompletion -Provider AzureOpenAI -AzureOpenAIProtocol Responses -DeploymentChat model -SystemPrompt system -UserPrompt user -MaxTokens 256 -TimeOut 60 -Stream $false -LogFolder $EvidenceRoot; Assert ($r -eq 'AZURE_OK' -and $script:posts -eq 1) 'route/count' }
Check 'no-retry' {$script:fail=$true;$caught=$false;try{Invoke-LLMChatCompletion -Provider AzureOpenAI -AzureOpenAIProtocol Responses -DeploymentChat model -MaxTokens 256 -TimeOut 60 -Stream $false -LogFolder $EvidenceRoot -ErrorAction Stop|Out-Null}catch{$caught=$true};Assert ($caught -and $script:posts -eq 2) 'retry or fallback'}
@{runtime=$PSVersionTable.PSVersion.ToString();sourceHash=(Get-FileHash $SourcePath).Hash;parseErrors=$e.Count;cases=$rows}|ConvertTo-Json -Depth 15|Set-Content (Join-Path $EvidenceRoot 'receipt.json') -Encoding UTF8
$rows|ForEach-Object {"$($_.id): $($_.pass)"}
if($e.Count -or @($rows|Where-Object {-not $_.pass}).Count){exit 1}
